enum FetchStrategy { JOIN, TWO_QUERIES }
Order findByIdWithItems(long id, FetchStrategy strategy) throws SQLException {
  return switch (strategy) {
    case JOIN -> findByIdWithItemsUsingJoin(id);
    case TWO_QUERIES -> findByIdWithItemsUsingTwoQueries(id);
  };
}

